    "purpose": "Bu dersin amacı, Osmanlı arşiv belgelerine giriş niteliğinde temel bilgi ve becerileri kazandırmaktır. Öğrencilerin Osmanlıca belge okuma, temel paleografi bilgisi edinme ve arşiv belgelerini tanıma becerilerini geliştirmesi hedeflenmektedir.",
    "content": "Osmanlı arşiv sistemine giriş, belge türlerinin tanıtımı, Osmanlı Türkçesi yazı türleri, temel paleografi, belge okuma teknikleri ve basit metinlerin transkripsiyonu dersin kapsamını oluşturmaktadır.",
