    "content": "Cumhuriyet dönemi tarihi vesikalar; Millî Mücadele'nin tarihsel bağlamı, siyasal ve askerî gelişmeler, kurumsal dönüşüm, toplumsal ve ekonomik değişim, dış politika, belge ve söylevlerin tenkidi, hafıza ve tarih yazımı, güncel historiografik yaklaşımlar boyutlarıyla ele alınır.",
